mapper.select:
SELECT n.notification_id, n.recipient_member_id, n.notification_type, n.settlement_id,
       n.actor_name, n.gathering_name, n.amount, n.currency_code,
       n.read_at, n.created_at
FROM notifications n
WHERE n.recipient_member_id = #{memberId}
  AND n.deleted_at IS NULL

  AND (n.created_at, n.notification_id) < (
      SELECT c.created_at, c.notification_id
      FROM notifications c
      WHERE c.notification_id = #{cursor}
        AND c.recipient_member_id = #{memberId}
  )

ORDER BY n.created_at DESC, n.notification_id DESC
LIMIT #{limit}

mapper.update:
UPDATE notifications n
SET n.read_at = #{readAt}
WHERE n.recipient_member_id = #{memberId}
  AND n.read_at IS NULL
  AND n.deleted_at IS NULL

UPDATE notifications n
SET n.read_at = #{readAt}
WHERE n.notification_id = #{notificationId}
  AND n.recipient_member_id = #{memberId}
  AND n.read_at IS NULL
  AND n.deleted_at IS NULL

UPDATE notifications n
SET n.deleted_at = #{deletedAt}
WHERE n.notification_id = #{notificationId}
  AND n.recipient_member_id = #{memberId}
  AND n.deleted_at IS NULL

UPDATE notifications n
SET n.deleted_at = #{deletedAt}
WHERE n.recipient_member_id = #{memberId}
  AND n.deleted_at IS NULL

